(function(){
'use strict';
const FLOW='20260916-live-chat-v8';
const AVATAR='/static/ariella-avatar-approved.jpg?v=20260916-live-v8';
function isTrip(){return location.pathname.indexOf('/trip/new')===0||!!document.getElementById('tripWizard');}
function firstName(p){return String(p.first_name||p.name||p.full_name||'').trim().split(/\s+/)[0]||'';}
function removeQuestionnaire(){document.querySelectorAll('#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar,#tripWizard').forEach(x=>{x.style.display='none';});}
function addStyles(){if(document.getElementById('ariella-live-v8-style'))return;const s=document.createElement('style');s.id='ariella-live-v8-style';s.textContent='#tripWizard,#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar{display:none!important}#ariellaDesktopChat{width:min(1100px,94%);margin:16px auto 36px;direction:rtl;font-family:Arial,"Segoe UI",sans-serif}.ac-chat{background:#fffaf2;border:1px solid rgba(201,154,63,.38);border-radius:22px;overflow:hidden;height:min(720px,calc(100dvh - 135px));min-height:540px;display:flex;flex-direction:column}.ac-head{display:flex;align-items:center;gap:12px;padding:14px 18px;background:#123437;color:#fff;font-size:20px;font-weight:800}.ac-head img{width:54px!important;height:54px!important;min-width:54px!important;max-width:54px!important;object-fit:cover!important;border-radius:50%!important;border:2px solid #d9b56d!important}.ac-messages{flex:1;min-height:0;padding:18px 16px;display:flex;flex-direction:column;gap:14px;overflow-y:auto}.ac-row{display:flex;align-items:flex-start;gap:8px}.ac-row.user{justify-content:flex-start;flex-direction:row-reverse}.ac-avatar{width:36px!important;height:36px!important;min-width:36px!important;max-width:36px!important;flex:0 0 36px!important;border-radius:50%;overflow:hidden}.ac-avatar img{display:block!important;width:36px!important;height:36px!important;object-fit:cover!important;border-radius:50%!important}.ac-bubble{max-width:min(78%,620px);padding:12px 14px;border-radius:16px;background:#fff;border:1px solid #eadfc8;white-space:pre-line;line-height:1.55;font-size:17px}.ac-row.user .ac-bubble{background:#dff3f5;border-color:#b7dde1}.ac-compose{padding:10px;border-top:1px solid #eadfc8;background:#fff;display:flex;gap:10px}.ac-compose textarea{flex:1;min-height:48px;max-height:120px;border:1px solid #d9cdb8;border-radius:14px;padding:12px;font:inherit;resize:none}.ac-send{height:48px;min-width:72px;border:0;border-radius:13px;background:#0b8f9c;color:#fff;font-weight:800}@media(max-width:700px){#ariellaDesktopChat{width:100%;margin:0 auto 20px;padding:8px 10px}.ac-chat{height:calc(100dvh - 120px);min-height:520px;border-radius:16px}.ac-head{font-size:17px;padding:11px 13px}.ac-head img{width:46px!important;height:46px!important;min-width:46px!important;max-width:46px!important}.ac-messages{padding:14px 10px}.ac-bubble{max-width:82%;font-size:16px}}';document.head.appendChild(s);}
function makeChat(){const old=document.getElementById('ariellaDesktopChat');if(old)old.remove();const c=document.createElement('section');c.id='ariellaDesktopChat';c.dataset.engineOwner='live-chat-v8';c.innerHTML='<div class="ac-chat"><div class="ac-head"><img src="'+AVATAR+'" alt="אריאלה"><span>אריאלה — סוכנת הנסיעות האישית שלך</span></div><div class="ac-messages" id="ariellaChatMessages"></div><div class="ac-compose"><textarea id="ariellaChatInput" rows="1" aria-label="כתיבת הודעה"></textarea><button id="ariellaChatSend" class="ac-send" type="button">שליחה</button></div></div>';const w=document.getElementById('tripWizard'),m=document.querySelector('main');if(w&&w.parentNode)w.parentNode.insertBefore(c,w);else if(m)m.appendChild(c);return c;}
async function loadName(profile){if(firstName(profile))return;try{const r=await fetch('/account',{credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const html=await r.text(),doc=new DOMParser().parseFromString(html,'text/html'),text=(doc.body&&doc.body.innerText)||'',m=text.match(/שלום\s*[,،:]?\s*([^\s,!.]+)/);if(m&&m[1])profile.first_name=m[1].trim();}catch(e){}}
function controller(chat){const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages');let profile={},history=[],busy=false;try{const current=JSON.parse(localStorage.getItem('ariellaChatState:v8')||'null');if(current){profile=current.profile||{};history=Array.isArray(current.history)?current.history:[];}else{for(const key of ['ariellaChatState:v7','ariellaChatState:v6','ariellaChatState:v4']){const old=JSON.parse(localStorage.getItem(key)||'null');if(old&&old.profile){profile=old.profile;break;}}}}catch(e){}
const save=()=>{try{localStorage.setItem('ariellaChatState:v8',JSON.stringify({profile,history:history.slice(-80),flow:FLOW,saved_at:new Date().toISOString()}));}catch(e){}};
const add=(role,text)=>{if(!String(text||'').trim())return;const r=document.createElement('div');r.className='ac-row '+(role==='assistant'?'bot':'user');if(role==='assistant'){const a=document.createElement('span');a.className='ac-avatar';const img=document.createElement('img');img.src=AVATAR;img.alt='אריאלה';a.appendChild(img);r.appendChild(a);}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;r.appendChild(b);messages.appendChild(r);messages.scrollTop=messages.scrollHeight;};
async function start(){messages.innerHTML='';if(history.length){history.forEach(x=>add(x.role,x.content));return;}await loadName(profile);const n=firstName(profile),g=(n?'היי '+n+' 😊':'היי 😊')+'\nאני אריאלה. מה מתחשק לך לתכנן?';add('assistant',g);history.push({role:'assistant',content:g});save();}
async function talk(){const text=input.value.trim();if(!text||busy)return;busy=true;send.disabled=true;input.value='';add('user',text);const prior=history.slice(-24);history.push({role:'user',content:text});save();try{const r=await fetch('/api/ariella/chat-clean',{method:'POST',headers:{'Content-Type':'application/json','X-Ariella-Client':'live-chat-v8'},credentials:'same-origin',cache:'no-store',body:JSON.stringify({message:text,history:prior,profile})});let data={};try{data=await r.json();}catch(e){}if(!r.ok||data.status!=='success')throw new Error(data.message||'chat error');if(data.engine_version!=='live-chat-v8'){add('assistant','הגרסה החדשה עדיין נפרסת. רענני בעוד רגע.');return;}document.documentElement.dataset.ariellaEngine=data.engine_version;profile=data.profile||profile;const reply=String(data.reply||'').trim();if(reply){add('assistant',reply);history.push({role:'assistant',content:reply});save();}}catch(e){add('assistant','יש כרגע תקלה זמנית בחיבור. נסי שוב בעוד רגע.');}finally{busy=false;send.disabled=false;input.focus();}}
send.addEventListener('click',e=>{e.preventDefault();talk();});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();talk();}});start();}
function boot(){if(!isTrip())return;removeQuestionnaire();addStyles();controller(makeChat());}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();